<?php
require_once __DIR__.'/opportunities.php';require_once __DIR__.'/business.php';require_once __DIR__.'/operations.php';
// Tenant connections, structured AI actions, and durable automation jobs.
function platformSchema($pdo){
$pdo->exec("CREATE TABLE IF NOT EXISTS aulieata_connections(user_id INT PRIMARY KEY,bot_id BIGINT NOT NULL UNIQUE,username VARCHAR(100) NOT NULL,token_box TEXT NOT NULL,route_key VARCHAR(64) NOT NULL UNIQUE,secret_box TEXT NOT NULL,active TINYINT DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS aulieata_tg_events(user_id INT NOT NULL,update_id BIGINT NOT NULL,chat_id BIGINT NOT NULL,status VARCHAR(20) DEFAULT 'processing',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,update_id),INDEX owner_chat(user_id,chat_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS aulieata_jobs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,task VARCHAR(40) NOT NULL,hour_local TINYINT NOT NULL DEFAULT 9,enabled TINYINT DEFAULT 1,next_run DATETIME NOT NULL,last_run DATETIME NULL,last_status VARCHAR(30) DEFAULT 'waiting',UNIQUE KEY owner_task(user_id,task)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS aulieata_job_runs(id BIGINT AUTO_INCREMENT PRIMARY KEY,job_id BIGINT NOT NULL,user_id INT NOT NULL,run_day DATE NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY daily_job(job_id,run_day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
}
function sealToken($text,$cfg){$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($text,'aes-256-gcm',hash('sha256',$cfg['encryption_key']??$cfg['webhook_secret'],true),OPENSSL_RAW_DATA,$iv,$tag);if($cipher===false)throw new RuntimeException('Encryption unavailable');return base64_encode($iv.$tag.$cipher);}
function openToken($box,$cfg){$raw=base64_decode($box,true);if(!$raw||strlen($raw)<29)throw new RuntimeException('Connection unavailable');$v=openssl_decrypt(substr($raw,28),'aes-256-gcm',hash('sha256',$cfg['encryption_key']??$cfg['webhook_secret'],true),OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16));if($v===false)throw new RuntimeException('Connection unavailable');return $v;}
function telegramCall($token,$method,$data=[]){$ch=curl_init('https://api.telegram.org/bot'.$token.'/'.$method);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>25,CURLOPT_POSTFIELDS=>$data]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$r=json_decode((string)$raw,true);if($code!==200||!($r['ok']??false))throw new RuntimeException('Telegram отклонил запрос. Проверьте токен и доступность бота.');return $r['result'];}
function connectionStatus($pdo,$uid){$q=$pdo->prepare('SELECT username,active,updated_at FROM aulieata_connections WHERE user_id=?');$q->execute([$uid]);return $q->fetch()?:null;}
function platformAI($cfg,$system,$text,$limit=10000){$key=$cfg['gemini_key']??getenv('GEMINI_API_KEY');if(!$key)throw new RuntimeException('ИИ не настроен');$body=['systemInstruction'=>['parts'=>[['text'=>$system]]],'contents'=>[['role'=>'user','parts'=>[['text'=>$text]]]],'generationConfig'=>['maxOutputTokens'=>min(10000,max(1000,(int)$limit)),'responseMimeType'=>'application/json']];foreach(['gemini-3.8-flash','gemini-3.5-flash-lite'] as $model){$ch=curl_init('https://generativelanguage.googleapis.com/v1beta/models/'.$model.':generateContent');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>12,CURLOPT_TIMEOUT=>65,CURLOPT_HTTPHEADER=>['Content-Type: application/json','x-goog-api-key: '.$key],CURLOPT_POSTFIELDS=>json_encode($body,JSON_UNESCAPED_UNICODE)]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if(!in_array($code,[0,429,500,502,503,504]))break;}if($code!==200)throw new RuntimeException($code===429?'Квота ИИ исчерпана. Повторите позже.':'ИИ временно недоступен. Данные не изменены.');$r=json_decode((string)$raw,true);$text='';foreach($r['candidates'][0]['content']['parts']??[] as $part)if(isset($part['text'])&&empty($part['thought']))$text.=$part['text'];$json=json_decode($text,true);if(!is_array($json))throw new RuntimeException('ИИ не смог разобрать данные. Уточните задачу.');return $json;}
function platformRecord($pdo,$uid,$kind,$data){$q=$pdo->prepare('INSERT INTO aulieata_records(user_id,kind,payload) VALUES(?,?,?)');$q->execute([$uid,$kind,json_encode($data,JSON_UNESCAPED_UNICODE)]);return (int)$pdo->lastInsertId();}
function cleanImportRow($kind,$d){if(!is_array($d))throw new RuntimeException('Проверьте строку');$str=fn($k,$n=180)=>mb_substr(trim((string)($d[$k]??'')),0,$n);$name=$str('name');if(!$name)throw new RuntimeException('Нужно название / имя');if($kind==='catalog'){$price=filter_var(str_replace(',','.',(string)($d['price']??'')),FILTER_VALIDATE_FLOAT);$cost=filter_var($d['cost']??0,FILTER_VALIDATE_FLOAT);$qty=filter_var($d['quantity']??0,FILTER_VALIDATE_INT);if($price===false||$price<=0||$price>1000000000||$cost===false||$cost<0||$qty===false||$qty<0||$qty>100000000)throw new RuntimeException('Проверьте цену, себестоимость и количество продаж');return ['name'=>$name,'price'=>round($price,2),'cost'=>round($cost,2),'quantity'=>$qty,'category'=>$str('category',80)?:'Основное','sku'=>$str('sku',80),'unit'=>$str('unit',80),'description'=>$str('description',700),'aliases'=>$str('aliases',400),'availability'=>$str('availability',30)?:'unknown','data_mode'=>$str('data_mode',20)?:'live'];}
if(in_array($kind,['stock_batches','business_capacity']))return cleanOpportunityResource($kind,$d);
if($kind==='clients')return ['name'=>$name,'phone'=>$str('phone',40),'email'=>$str('email'),'note'=>$str('note',3000),'status'=>'Новый'];
if($kind==='expenses'){$v=filter_var(str_replace(',','.',(string)($d['amount']??'')),FILTER_VALIDATE_FLOAT);if($v===false||$v<=0||$v>1000000000)throw new RuntimeException('Проверьте сумму расхода');return ['name'=>$name,'amount'=>round($v,2),'date'=>$str('date',20)?:date('Y-m-d'),'category'=>$str('category',100)?:'Импорт'];}
if($kind==='knowledge'){$t=$str('text',4000);if(!$t)throw new RuntimeException('Нужен текст ответа');return ['name'=>$name,'text'=>$t,'audience'=>($d['audience']??'internal')==='public'?'public':'internal'];}
if($kind==='documents'||$kind==='tasks'){$t=$str('text',12000);if(!$t)throw new RuntimeException('Нужно описание');return ['name'=>$name,'text'=>$t,'status'=>'Новая'];}throw new RuntimeException('Неизвестный тип данных');}
function commitRows($pdo,$uid,$kind,$rows){$ids=[];$skipped=0;foreach($rows as $d){if($kind==='catalog'){$q=$pdo->prepare('SELECT c.id FROM business_catalog c LEFT JOIN aulieata_catalog_status a ON a.user_id=c.user_id AND a.item_id=c.id WHERE c.user_id=? AND c.item_name=? AND c.item_price=? AND COALESCE(a.archived,0)=0 LIMIT 1');$q->execute([$uid,$d['name'],$d['price']]);if($q->fetchColumn()){$skipped++;continue;}$q=$pdo->prepare('INSERT INTO business_catalog(user_id,item_name,item_price,item_cost,units_sold,category) VALUES(?,?,?,?,?,?)');$q->execute([$uid,$d['name'],$d['price'],$d['cost'],$d['quantity'],$d['category']]);$newId=(int)$pdo->lastInsertId();$details=catalogDetails($d,businessProfile($pdo,$uid)['type']);opsValidateCatalog($pdo,$uid,$newId,$details);saveCatalogDetails($pdo,$uid,$newId,$details);$ids[]=$newId;}else{$ids[]=platformRecord($pdo,$uid,$kind,$d);}}return ['ids'=>$ids,'count'=>count($ids),'skipped'=>$skipped];}
function nextJobTime($hour){$d=new DateTime('today',new DateTimeZone('Asia/Qyzylorda'));$d->setTime($hour,0);if($d<=new DateTime('now',new DateTimeZone('Asia/Qyzylorda')))$d->modify('+1 day');return $d->format('Y-m-d H:i:s');}
function runBusinessJob($pdo,$job){$uid=(int)$job['user_id'];$text='';$title='';if($job['task']==='daily_digest'){$q=$pdo->prepare("SELECT COUNT(*) FROM aulieata_bookings WHERE user_id=? AND status='confirmed' AND DATE(starts_at)=?");$q->execute([$uid,(new DateTime('now',new DateTimeZone('Asia/Qyzylorda')))->format('Y-m-d')]);$n=$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM aulieata_records WHERE user_id=? AND kind='telegram' AND archived=0");$q->execute([$uid]);$title='Ежедневная сводка';$text='Записей на сегодня: '.$n."\nОбращений в Telegram (активная история): ".$q->fetchColumn()."\nПроверьте входящие сообщения и ближайшие записи.";}elseif($job['task']==='catalog_audit'){$q=$pdo->prepare('SELECT c.item_name,c.item_price,c.item_cost FROM business_catalog c LEFT JOIN aulieata_catalog_status a ON a.user_id=c.user_id AND a.item_id=c.id WHERE c.user_id=? AND COALESCE(a.archived,0)=0');$q->execute([$uid]);$rows=$q->fetchAll();$lines=[];foreach($rows as $r)if((float)$r['item_price']<=(float)$r['item_cost'])$lines[]=$r['item_name'].' — цена не выше себестоимости';$title='Проверка каталога';$text='Активных позиций: '.count($rows)."\n".($lines?implode("\n",$lines):'Позиций с ценой не выше себестоимости не найдено.');}elseif($job['task']==='inbox_followup'){$q=$pdo->prepare("SELECT payload FROM aulieata_records WHERE user_id=? AND kind='telegram' AND archived=0 ORDER BY id DESC LIMIT 500");$q->execute([$uid]);$n=0;foreach($q->fetchAll(PDO::FETCH_COLUMN) as $raw){$d=json_decode($raw,true);if(in_array($d['status']??'done',['failed','processing']))$n++;}$title='Контроль обращений';$text='Обращений с ошибкой или незавершённой обработкой: '.$n.'. Просмотрите Telegram → входящие.';}elseif($job['task']==='opportunity_check'){$signals=scanBusinessSignals($pdo,$uid);$title='Риски и возможности';$text=$signals?implode("\n",array_map(fn($s)=>$s['name'].' — '.$s['title'],$signals)):'По внесённым ресурсам срочных сигналов не найдено.';}elseif($job['task']==='promotion_auto'){$cfg=require dirname(__DIR__).'/aulieata-secrets.php';$profile=businessProfile($pdo,$uid);$candidates=promotionCandidates(scanBusinessSignals($pdo,$uid),20);$title='Автоматические идеи акций';if(!$candidates||$profile['type']==='medical'){$text='Подходящих безопасных ресурсов для акции с маржой от 20% не найдено.';}else{$ids=buildPromotionDrafts($pdo,$uid,20,$profile,$cfg);$text='Подготовлено черновиков: '.count($ids).'. Проверьте их в разделе Риски и акции. Ничего не опубликовано автоматически.';}}else throw new RuntimeException('Unknown job');return platformRecord($pdo,$uid,'automation_logs',['name'=>$title,'text'=>$text,'job_id'=>$job['id']]);}
function runDueJobs($pdo){$now=(new DateTime('now',new DateTimeZone('Asia/Qyzylorda')))->format('Y-m-d H:i:s');$day=substr($now,0,10);$q=$pdo->prepare('SELECT * FROM aulieata_jobs WHERE enabled=1 AND next_run<=? ORDER BY next_run LIMIT 50');$q->execute([$now]);$count=0;foreach($q->fetchAll() as $job){$claim=$pdo->prepare("INSERT IGNORE INTO aulieata_job_runs(job_id,user_id,run_day,status) VALUES(?,?,?,'running')");$claim->execute([$job['id'],$job['user_id'],$day]);if(!$claim->rowCount())continue;try{runBusinessJob($pdo,$job);$status='done';$count++;}catch(Throwable $e){$status='failed';}$r=$pdo->prepare('UPDATE aulieata_job_runs SET status=? WHERE job_id=? AND run_day=?');$r->execute([$status,$job['id'],$day]);$r=$pdo->prepare('UPDATE aulieata_jobs SET last_run=?,last_status=?,next_run=? WHERE id=?');$r->execute([$now,$status,nextJobTime((int)$job['hour_local']),$job['id']]);}return $count;}
